from typing import List

def remove_duplicates(numbers: List[int]) -> List[int]:
    counts = {}
    for number in numbers:
        counts[number] = counts.get(number, 0) + 1
    return [number for number in numbers if counts[number] == 1]
    # We need to only return those numbers which have a count of one, keeping the order as is.

def fizz_buzz(n: int):
    count = 0
    for i in range(n):
        if i % 11 == 0 or i % 13 == 0:
            count += str(i).count('7')
    return count

def median(l: list):
    """Return median of elements in the list l."""
    l_sorted = sorted(l)
    n = len(l_sorted)
    mid = n // 2
    if n % 2 == 1:
        return l_sorted[mid]
    else:
        return (l_sorted[mid - 1] + l_sorted[mid]) / 2.0

def largest_prime_factor(n: int):
    i = 2
    last_prime = 0
    while i * i <= n:
        if n % i:
            i += 1
        else:
            last_prime = i
            n //= i
    if n > 1:
        last_prime = n
    return last_prime

def correct_bracketing(brackets: str):
    balance = 0
    for char in brackets:
        if char == '(':  
            balance += 1
        elif char == ')':
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def vowels_count(s):
    vowels = 'aeiou'
    count = 0
    for i in range(len(s)):
        if s[i].lower() in vowels:
            count += 1
        elif s[i].lower() == 'y' and i == len(s) - 1:
            count += 1
    return count

def total_match(lst1, lst2):
    total_chars_lst1 = sum(len(s) for s in lst1)
    total_chars_lst2 = sum(len(s) for s in lst2)
    if total_chars_lst1 < total_chars_lst2:
        return lst1
    return lst2 if total_chars_lst1 > total_chars_lst2 else lst1

def anti_shuffle(s):
    words = s.split(' ')
    ordered_words = []
    for word in words:
        letters = sorted(c for c in word if c.isalnum())  # Sort only alphanumeric characters
        letter_index = 0
        ordered_word = ''
        for char in word:
            if char.isalnum():
                ordered_word += letters[letter_index]
                letter_index += 1
            else:
                ordered_word += char  # Maintain spaces and punctuation in original position
        ordered_words.append(ordered_word)
    return ' '.join(ordered_words)

def next_smallest(lst):
    unique_elements = list(set(lst))
    if len(unique_elements) < 2:
        return None
    unique_elements.sort()
    return unique_elements[1]

def max_fill(grid, capacity):
    total_water = sum(sum(row) for row in grid)
    return total_water // capacity + (total_water % capacity > 0)

def minPath(grid, k):
    from heapq import heappop, heappush

    N = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    min_heap = []

    # Initialize the min heap with all starting points
    for i in range(N):
        for j in range(N):
            heappush(min_heap, (grid[i][j], [grid[i][j]], i, j))

    # While there are paths to explore
    while min_heap:
        value, path, x, y = heappop(min_heap)

        # If the path length is k, return the path
        if len(path) == k:
            return path

        # Explore neighbors
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N:
                heappush(min_heap, (path[-1] + grid[nx][ny], path + [grid[nx][ny]], nx, ny))

    return []

def is_equal_to_sum_even(n):
    """Evaluate whether the given number n can be written as the sum of exactly 4 positive even numbers"""
    return n >= 8 and n % 2 == 0

def sum_squares(lst):
    total = 0
    for i, x in enumerate(lst):
        if i % 3 == 0:
            total += x ** 2
        elif i % 4 == 0:
            total += x ** 3
        else:
            total += x
    return total

def order_by_points(nums):
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))
    return sorted(nums, key=lambda x: (digit_sum(x), nums.index(x)))

def x_or_y(n, x, y):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    return x if is_prime(n) else y

import hashlib

def string_to_md5(text):
    """
    Given a string 'text', return its md5 hash equivalent string.
    If 'text' is an empty string, return None.

    >>> string_to_md5('Hello world') == '3e25960a79dbc69b674cd4ec67a72c62'
    """
    if text == '':
        return None
    return hashlib.md5(text.encode()).hexdigest()
